"""Client-owned validation rules for requests sent to the weather backend."""


REQUEST_SCHEMA = {
    "required": ("city", "days", "units"),
    "types": {"city": str, "days": int, "units": str},
    "ranges": {"days": (1, 14)},
    "enums": {"units": ("metric", "imperial")},
}


def validate_payload(payload):
    """Return client-owned, structured validation errors for one request."""
    errors = []

    if not isinstance(payload, dict):
        return [{
            "field": "request",
            "message": "Request must be an object",
            "error": "wrong_type",
        }]

    # Check presence before type/range checks so malformed values do not
    # produce confusing secondary errors.
    for field in REQUEST_SCHEMA["required"]:
        if field not in payload or payload[field] is None or payload[field] == "":
            errors.append({
                "field": field,
                "message": f"Required field '{field}' is missing",
                "error": "missing",
            })

    for field, expected_type in REQUEST_SCHEMA["types"].items():
        if field in payload and payload[field] is not None and not isinstance(payload[field], expected_type):
            errors.append({
                "field": field,
                "message": f"'{field}' must be of type {expected_type.__name__}",
                "error": "wrong_type",
            })

    days = payload.get("days")
    if isinstance(days, int) and not isinstance(days, bool):
        minimum, maximum = REQUEST_SCHEMA["ranges"]["days"]
        if not minimum <= days <= maximum:
            errors.append({
                "field": "days",
                "message": f"'days' must be between {minimum} and {maximum}",
                "error": "out_of_range",
            })

    units = payload.get("units")
    if isinstance(units, str) and units not in REQUEST_SCHEMA["enums"]["units"]:
        allowed = ", ".join(REQUEST_SCHEMA["enums"]["units"])
        errors.append({
            "field": "units",
            "message": f"'units' must be one of: {allowed}",
            "error": "invalid_option",
        })

    return errors

